        $event = Event::factory()
            ->withLanding()
            ->inState(EventState::DRAFT)
            ->for($workspace)
            ->create([
                'created_by' => $owner->id,
                'title' => 'Ready Admin Managed Event',
            ]);
        $admin = $this->createPlatformSuperAdmin($workspace);

        $startsAt = now()->addDays(7)->setSecond(0);
        $endsAt = $startsAt->copy()->addHour();

        $this->actingAs($admin)
            ->patch(route('admin.events.update', $event->uuid), [
                'title' => 'Updated by SuperAdmin',
                'description' => 'Managed directly from the SuperAdmin event shell.',
                'starts_at' => $startsAt->format('Y-m-d\TH:i'),
                'ends_at' => $endsAt->format('Y-m-d\TH:i'),
                'timezone' => 'Europe/Istanbul',
            ])
            ->assertRedirect(route('admin.events.show', $event->uuid))
            ->assertSessionHas('status', __('events.edit.success'));

        $this->assertSame('Updated by SuperAdmin', $event->refresh()->title);
        $this->approveCurrentAuditSnapshot($event->refresh(), $admin);

        $this->actingAs($admin)
            ->postJson(route('admin.events.publish', $event->uuid))
            ->assertOk()
            ->assertJsonPath('data.state', EventState::PUBLISHED->value);

        $this->assertSame(EventState::PUBLISHED, $event->refresh()->state);
    }

    private function approveCurrentAuditSnapshot(Event $event, $actor): void
    {
        $request = app(AiAuditRequestService::class)->createOrReuseForEvent($event);
        $request->update(['status' => AiAuditRequestStatus::RESOLVED]);

        AiAuditVerdict::query()->create([
            'ai_audit_request_id' => $request->id,
            'actor_id' => $actor->id,
            'outcome' => AiAuditVerdictOutcome::APPROVE,
            'status' => AiAuditVerdictStatus::CURRENT,
            'decided_at' => now(),
        ]);
    }

