<?php

declare(strict_types=1);

namespace App\Modules\Events\Exceptions;

use RuntimeException;

/**
 * Base class for all Events module domain exceptions.
 * HTTP handlers translate via JKM-EVT-* error codes.
 */
abstract class EventDomainException extends RuntimeException
{
    abstract public function errorCode(): string;

    abstract public function httpStatus(): int;
}
<?php

declare(strict_types=1);

namespace App\Modules\Events\Exceptions;

use App\Modules\Events\Models\Event;

class EventStateLocked extends EventDomainException
{
    public function __construct(public readonly Event $event)
    {
        parent::__construct("Event {$event->getKey()} is locked in state {$event->state->value}");
    }

    public static function for(Event $event): self
    {
        return new self($event);
    }

    public function errorCode(): string
    {
        return 'JKM-EVT-1002';
    }

    public function httpStatus(): int
    {
        return 409;
    }
}
<?php

declare(strict_types=1);

namespace App\Modules\Events\Exceptions;

use App\Modules\Events\Enums\EventState;

class IllegalStateTransition extends EventDomainException
{
    public function __construct(
        public readonly EventState $from,
        public readonly EventState $to,
    ) {
        parent::__construct("Illegal event state transition: {$from->value} -> {$to->value}");
    }

    public static function between(EventState $from, EventState $to): self
    {
        return new self($from, $to);
    }

    public function errorCode(): string
    {
        return 'JKM-EVT-1001';
    }

    public function httpStatus(): int
    {
        return 422;
    }
}

