        // mask EventStateLocked or roll back unrelated writes. Success-path
        // audit STAYS inside the outer tx (AC1 atomic state+audit invariant).
        $result = DB::transaction(function () use ($event, $actor, $reason): array {
            $fresh = $this->events->lockEventForServiceWrite($event->getKey());

            if ($fresh->cancelled_at !== null) {
